/* vu0.h - VU0 in macro mode (COP2 instructions issued by the EE), and the register file the translated VU0
 * functions (vu0_funcs.c, generated by gen_vu0.py from the decomp's matched assembly) run on. */
#ifndef DOTR_VU0_H
#define DOTR_VU0_H

#include "../gfx_internal.h"

typedef struct vu0_state {
    vu_vec vf[32];
    u16    vi[16];
    vu_vec acc;
    u32    q, i, r, p;
    u32    status, mac, clip;
    u8     mem[4096];
} vu0_state;

extern vu0_state vu0;

void vu0_reset(void);
/* Execute one COP2 macro instruction (the raw 32-bit word, e.g. 0x4BE821BC = vmulax.xyzw ACC, vf4, vf8x). */
void vu0_cop2(u32 word);
/* cfc2/ctc2 on VU0 integer and control registers (0..15 = vi, 16 status, 17 MAC, 18 clip, 20 R, 21 I, 22 Q,
 * 28 FBRST, ...). */
u32  vu0_cfc2(u32 reg);
void vu0_ctc2(u32 reg, u32 v);

/* ---- the EE register file of translated functions -------------------------------------------------- */

typedef struct ee_gpr { u64 lo, hi; } ee_gpr;

typedef struct ee_regs {
    ee_gpr r[32];
    float  f[32];
    float  facc;
    int    fcc;          /* FPU condition */
    u64    lo, hi;       /* integer multiply/divide */
} ee_regs;

extern ee_regs ee;

#endif
